CREATE DATABASE IF NOT EXISTS kec_academic;
USE kec_academic;
CREATE TABLE IF NOT EXISTS students (roll_no VARCHAR(15) PRIMARY KEY, name VARCHAR(100) NOT NULL, department VARCHAR(20) NOT NULL, current_semester INT NOT NULL CHECK(current_semester BETWEEN 1 AND 8));
CREATE TABLE IF NOT EXISTS courses (course_code VARCHAR(20) PRIMARY KEY, title VARCHAR(150) NOT NULL, credits INT NOT NULL CHECK(credits > 0), course_type ENUM('THEORY','PRACTICAL','EMBEDDED') NOT NULL);
CREATE TABLE IF NOT EXISTS enrollments (id INT AUTO_INCREMENT PRIMARY KEY, roll_no VARCHAR(15) NOT NULL, course_code VARCHAR(20) NOT NULL, semester INT NOT NULL CHECK(semester BETWEEN 1 AND 8), classes_held INT NOT NULL DEFAULT 0, classes_attended INT NOT NULL DEFAULT 0, condonation_approved BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE(roll_no,course_code,semester), CHECK(classes_attended >= 0 AND classes_held >= classes_attended), FOREIGN KEY(roll_no) REFERENCES students(roll_no), FOREIGN KEY(course_code) REFERENCES courses(course_code));
CREATE TABLE IF NOT EXISTS assessment_marks (enrollment_id INT PRIMARY KEY, cia1 DECIMAL(5,2), cia2 DECIMAL(5,2), assignment_mark DECIMAL(5,2), ese DECIMAL(5,2), ese_absent BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY(enrollment_id) REFERENCES enrollments(id) ON DELETE CASCADE, CHECK(cia1 BETWEEN 0 AND 100), CHECK(cia2 BETWEEN 0 AND 100), CHECK(assignment_mark BETWEEN 0 AND 100), CHECK(ese BETWEEN 0 AND 100), CHECK(NOT(ese_absent AND ese IS NOT NULL)));
